script.setup:
// Rough.js draws a hand-drawn scene on an OffscreenCanvas a few times a second (each redraw
// wobbles, like boiling line animation); WebGL uploads it as a texture over a paper shader.
const mod = await ctx.utils.import("https://esm.sh/roughjs@4.6.6");
const rough = mod.default ?? mod;
const gl = ctx.gl, s = ctx.state;
Object.assign(s, { rough, canvas: null, rc: null, tex: gl.createTexture(), clock: 1e9, seed: 1 });
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
s.prog = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_ink; uniform vec2 u_resolution; uniform vec3 u_paper;
float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float noise(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y); }
void main(){
  vec2 q = v_uv * u_resolution / u_resolution.y;
  // Paper: fibres and blotches, darker towards the corners.
  float fib = noise(q * vec2(400.0, 60.0)) * 0.04 + noise(q * 8.0) * 0.05;
  vec3 paper = u_paper * (0.97 + fib) * (1.0 - 0.3 * pow(length(v_uv - 0.5), 2.0));
  vec4 ink = texture(u_ink, v_uv);
  // Ink takes on a little of the paper's grain.
  outColor = vec4(mix(paper, ink.rgb * (0.95 + fib), ink.a), 1.0);
}`);
s.wasDown = false;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const [w, h] = ctx.resolution;
if (!s.canvas || s.canvas.width !== w || s.canvas.height !== h) {
  s.canvas = new OffscreenCanvas(w, h);
  s.rc = s.rough.canvas(s.canvas);
  s.clock = 1e9;
}
s.clock += ctx.dt;
// Redraw at the boil rate; between redraws the same drawing stays up.
if (s.clock >= 1 / Math.max(u.u_boil, 0.01) || (u.u_boil === 0 && s.clock > 0.1)) {
  s.clock = 0;
  if (u.u_boil > 0) s.seed = 1 + Math.floor(Math.random() * 1e6);
  const g = s.canvas.getContext("2d"), rc = s.rc, t = ctx.time, k = h / 600, W = w / k;
  g.clearRect(0, 0, w, h);
  g.save(); g.scale(k, k);
  const hex = (c) => "#" + c.map((v) => Math.round(Math.min(1, Math.max(0, v)) * 255).toString(16).padStart(2, "0")).join("");
  const styles = ["hachure", "cross-hatch", "zigzag", "dots", "dashed", "zigzag-line", "solid"];
  const base = { roughness: u.u_roughness, bowing: u.u_bowing, strokeWidth: 1.6, hachureGap: u.u_gap, fillWeight: 1.2, fillStyle: styles[u.u_style], seed: s.seed };
  const o = (extra) => ({ ...base, ...extra });
  // Sun with turning rays.
  const sx = W * 0.8, sy = 120;
  rc.circle(sx, sy, 110, o({ fill: hex(u.u_sun), stroke: "#7a4a10" }));
  for (let i = 0; i < 12; i++) {
    const a = t * 0.3 + i * Math.PI / 6;
    rc.line(sx + Math.cos(a) * 70, sy + Math.sin(a) * 70, sx + Math.cos(a) * 100, sy + Math.sin(a) * 100, o({ stroke: "#b07020" }));
  }
  // Drifting clouds.
  for (let i = 0; i < 3; i++) {
    const cx = ((t * (14 + i * 6) + i * 300) % (W + 300)) - 150, cy = 70 + i * 55;
    rc.ellipse(cx, cy, 150, 50, o({ fill: "#ffffff", fillStyle: "solid", stroke: "#5a6a80" }));
    rc.ellipse(cx + 40, cy - 20, 90, 50, o({ fill: "#ffffff", fillStyle: "solid", stroke: "#5a6a80" }));
  }
  // Rolling hills.
  const hill = (y0, amp, ph, col) => {
    const pts = [[-40, 640]];
    for (let x = -40; x <= W + 40; x += 40) pts.push([x, y0 + Math.sin(x * 0.006 + ph) * amp]);
    pts.push([W + 40, 640]);
    rc.polygon(pts, o({ fill: hex(col), stroke: "#2c3b22" }));
  };
  hill(420, 30, 1.0, u.u_hills.map((v) => v * 1.15));
  hill(470, 25, 3.5, u.u_hills);
  // A house and a tree on the near hill.
  const hx = W * 0.3;
  rc.rectangle(hx, 380, 130, 100, o({ fill: hex(u.u_house), stroke: "#4a2a1a" }));
  rc.polygon([[hx - 15, 382], [hx + 65, 310], [hx + 145, 382]], o({ fill: "#8a3a2a", fillStyle: "cross-hatch", stroke: "#4a2a1a" }));
  rc.rectangle(hx + 50, 420, 30, 60, o({ fill: "#5a3a20", fillStyle: "solid", stroke: "#3a1a10" }));
  rc.rectangle(hx + 90, 400, 26, 26, o({ fill: "#ffe9a0", stroke: "#4a2a1a" }));
  const tx = W * 0.62, sway = Math.sin(t * 1.2) * 6;
  rc.line(tx, 470, tx + sway * 0.3, 380, o({ stroke: "#4a2a1a", strokeWidth: 4 }));
  rc.circle(tx + sway, 350, 110, o({ fill: "#3f7a3a", stroke: "#1f3a1a" }));
  // A balloon on a string follows the pointer.
  const [mx, my] = ctx.mouse;
  s.moved ||= mx !== 0.5 || my !== 0.5;
  const bx = s.moved ? mx * W : W * 0.12 + Math.sin(t * 0.7) * 30, by = s.moved ? my * 600 : 200 + Math.cos(t * 0.9) * 25;
  rc.curve([[bx, by + 40], [bx - 10, by + 90], [bx + 8, by + 140], [bx - 4, by + 190]], o({ stroke: "#333333", strokeWidth: 1 }));
  rc.ellipse(bx, by, 70, 85, o({ fill: hex(u.u_balloon), stroke: "#5a1020" }));
  g.restore();
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.canvas);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
}
gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_ink", s.tex, 0);
ctx.utils.drawFullscreen(s.prog);
